import logging

from robot.libraries.BuiltIn import BuiltIn

from .loader import ConfigsLoader, TestlineParametersLoader, TafConfigLoaderRFS, TafConfigLoaderSBTS
from .utils import config_vars_to_dict
from .rfs_utils import process_hran_variable_list


class hran_testline_configuration(object):

    ROBOT_LIBRARY_SCOPE = 'GLOBAL'

    def __init__(self, location, testline):
        self.location, self.testline = location, testline
        self.BuiltIn = BuiltIn

    def set_config_variables(self, *args, **kwargs):
        """
        Makes given variables available everywhere within the scope of the current suite.
        Variables values are taken from yaml configuration files.

        | **Author:** Agnieszka.Malek@nokia.com
        | **Maintainer:** Sebastian.Burniak@nokia.com (if neccesary)
        | **Released with version:** 1.0.0

         **Input Parameters:**

        +------------------+------+------------------------+
        | Parameter name   | Man. | Description            |
        +==================+======+========================+
        | args, kwargs     | no   | Variables to set       |
        +------------------+------+------------------------+

        **RETURN VALUE**

        - None

        **Example of simple usage:**

        .. code-block:: robotframework

            Config Files

            ::
            config.yaml

                CONFIG_VARIABLES:
                    - RNC=RNC_ID
                    - BSC=BSC_ID

                DICT_CONFIG_VARIABLES:
                    RNC: RNC_ID
                    BSC: BSC_ID

            ::
            BSC.yaml

                BSC_ID:
                    ip: 10.10.10.10
                    user: Fake
                    password: Fake

            ::

            RNC.yaml

                RNC_ID
                    ip: 10.10.10.10
                    user: Joke
                    password: Joke

            | `Set Config Variable` | Fairyland | JokeBTS_123_AlwaysWork | @{CONFIG VARIABLES}     |             |
            | `Set Config Variable` | Fairyland | JokeBTS_123_AlwaysWork | &{DICT_CONFIG_VARIABLES}|             |
            | `Set Config Variable` | Fairyland | JokeBTS_123_AlwaysWork | BSC_ID                  |             |
            | `Set Config Variable` | Fairyland | JokeBTS_123_AlwaysWork | RNC_ID                  | BSC=BSC_ID  |

            In first example ${RNC} and ${BSC} suite variables are set with ip, password and user data for BSC_ID and
            RNC_ID respectively.
            Second example will give the same results as the first one.
            Third example will set ${BSC_ID} variable with BSC_ID ip, user and password for BSC_ID from BSC.yaml.
            In forth example ${RNC_ID} ans ${BSC} variables are created with ip, user and password for RNC_ID from RNC.yaml
            and BSC_ID from BSC.yaml respectively.

        """
        configuration = ConfigsLoader(self.location, self.testline).get_config_parameters()
        config_variables_map = [arg for arg in args if '=' in arg]
        config_variables_map = dict(config_vars_to_dict(config_variables_map), **kwargs)
        for desired_key, config_var_key in config_variables_map.items():
            if config_var_key in configuration.keys():
                self.BuiltIn().set_suite_variable('${var_name}'.format(var_name=desired_key),
                                                  configuration[config_var_key])
            else:
                logging.warning('Key: {config_var_key} not found in testline configuration parameters'.format(
                    config_var_key=config_var_key))

        args = [arg for arg in args if '=' not in arg]
        for arg in args:
            if arg in configuration.keys():
                self.BuiltIn().set_suite_variable('${var_name}'.format(var_name=arg), configuration[arg])

    def set_testline_variables(self, env_config_id=1):
        """
        Makes testline configuration variables available everywhere within the scope of the current suite.
        Configuration variables are collected based on testline env_config with specified id.

        | **Author:** Agnieszka.Malek@nokia.com
        | **Maintainer:** Sebastian.Burniak@nokia.com (if neccesary)
        | **Released with version:** 1.0.0

         **Input Parameters:**

        +------------------+------+---------------------------+
        | Parameter name   | Man. | Description               |
        +==================+======+===========================+
        | env_config_id    | no   | Env config id. Default=1  |
        +------------------+------+---------------------------+

        **RETURN VALUE**

        - None

        **Example of simple usage:**

        .. code-block:: robotframework

            | `Set Testline Variables` | Fairyland | JokeBTS_123_AlwaysWork |   |
            | `Set Testline Variables` | Fairyland | JokeBTS_123_AlwaysWork | 2 |
        """

        testline_configuration = self._testline_parameters(env_config_id)
        for interface, params in testline_configuration.items():
            self.BuiltIn().set_suite_variable('${var_name}'.format(var_name=interface), params)

    def _testline_parameters(self, env_config_id, *args):
        testline = TestlineParametersLoader(self.location, self.testline, env_config_id, *args)
        return testline.testline_parameters.config

    def set_taf_config_variables(self, project="SBTS", config_var=None):
        """
        Makes testline configuration variables available everywhere within the scope of the current suite.
        Configuration variables are collected based on testline __init__.py with specified id.

        | **Author:** marcin.wieliczko@nokia.com
        | **Maintainer:** marcin.wieliczko@nokia.com
        | **Released with version:** 1.3.0

         **Input Parameters:**

        +------------------+------+------------------------------+
        | Parameter name   | Man. | Description                  |
        +==================+======+==============================+
        | project          | no   | Project name. Default='SBTS' |
        +------------------+------+------------------------------+

        **RETURN VALUE**

        - None

        **Example of simple usage:**

        .. code-block:: robotframework

            | `Set Taf Config Variables` | RFS |

        """

        if "RFS" in project:
            configuration = TafConfigLoaderRFS(self.location, self.testline, config_var)
        else:
            configuration = TafConfigLoaderSBTS(self.location, self.testline)
        logging.info(configuration.testline_parameters)
        for var in configuration.testline_parameters.keys():
            self.BuiltIn().set_suite_variable('${var_name}'.format(var_name=var),
                                              configuration.testline_parameters[var])

    def set_dict_taf_config_variables(self, project="SBTS"):
        """
        Makes testline configuration variables in dict format

        | **Author:** alexandru.stamp@nokia.com
        | **Maintainer:** alexandru.stamp@nokia.com
        | **Released with version:** 1.3.0

         **Input Parameters:**

        +------------------+------+------------------------------+
        | Parameter name   | Man. | Description                  |
        +==================+======+==============================+
        | project          | no   | Project name. Default='SBTS' |
        +------------------+------+------------------------------+

        **RETURN VALUE**

        - None

        **Example of simple usage:**

        .. code-block:: robotframework

            | `Set Dict Taf Config Variables` | RFS |

        """

        if "RFS" in project:
            configuration = TafConfigLoaderRFS(self.location, self.testline)
        else:
            configuration = TafConfigLoaderSBTS(self.location, self.testline)
        return configuration.testline_parameters

    def get_alias_list(self, variable_list):
        """
        Creates list of aliases from the supplied list based on the name of the variables,
        For example, if supplied the following list: [MASTER, SLAVE, BSC, SLAVE1, UE], will return MASTER, SLAVE, SLAVE1

        | **Author:** alexandru.stamp@nokia.com
        | **Maintainer:** alexandru.stamp@nokia.com
        | **Released with version:** 1.4.20

         **Input Parameters:**

        +------------------+------+------------------------------+
        | Parameter name   | Man. | Description                  |
        +==================+======+==============================+
        | variable_list    | yes  | Variable list                |
        +------------------+------+------------------------------+

        **RETURN VALUE**

        - Alias list

        **Example of simple usage:**

        .. code-block:: robotframework

            | `Get Alias List` | MASTER, SLAVE, BSC, RNC, SLAVE2 |

        """
        return process_hran_variable_list(variable_list)
